import itertools
import re


def _build_pattern():
    """Alternating digit-unit groups, each unit used at most once, in h/m/s order."""
    parts = []
    for length in range(1, 4):
        for combo in itertools.permutations('hms', length):
            if list(combo).sort() == list(combo):
                parts.append(r'(?:\d+' + ''.join(combo) + r')')
    return '^' + '|'.join(parts) + '$'


_PATTERN = re.compile(_build_pattern())
_FACTORS = {'h': 3600, 'm': 60, 's': 1}


def parse_duration(s):
    match = _PATTERN.match(s)
    if not match:
        raise ValueError("invalid duration {!r}".format(s))

    total = 0
    for token in match.groups():
        digits, unit = token[:-1], token[-1]
        total += int(digits) * _FACTORS[unit]
    return total
